// Title: Combine a TIFF image rendered from an Aspose.Cells worksheet with an external PNG using C# and a .NET imaging library
// AI Prompts: Generate C# code that uses Aspose.Cells to export the first worksheet to a TIFF file, then loads that TIFF and a separate PNG with System.Drawing (or ImageSharp) and overlays the PNG onto the TIFF. | Write a C# method that renders a workbook sheet as TIFF via Aspose.Cells, reads the TIFF and an external raster image with a .NET imaging library, composites them, and saves the merged result.
// Common Searches: how to overlay a PNG on a TIFF generated by Aspose.Cells in C# | C# merge exported Excel worksheet TIFF with another image using ImageSharp | combine Aspose.Cells TIFF output with external raster image programmatically
// Tags: Aspose.Cells export worksheet to TIFF | C# overlay PNG on TIFF image | ImageSharp composite raster images | merge Excel rendered TIFF with external picture | SheetRender generate TIFF from worksheet

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// Shows how to create a workbook, optionally add a picture, export the first worksheet to a TIFF file with Aspose.Cells, and then use a .NET imaging library to load the TIFF and an external PNG, overlay the PNG onto the TIFF, and save the combined image, including handling for missing files and exceptions.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and add sample data
            var workbook = new Workbook();
            var sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Hello");
            sheet.Cells["B1"].PutValue("World");

            // Path to the overlay raster image
            string overlayPath = "overlay.png";

            // Add picture if the overlay image exists
            if (File.Exists(overlayPath))
            {
                try
                {
                    // Add picture at the top‑left corner (row 0, column 0)
                    sheet.Pictures.Add(0, 0, overlayPath);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Failed to add overlay image: {ex.Message}");
                }
            }
            else
            {
                Console.WriteLine($"Overlay image not found: {overlayPath}");
            }

            // Set image options to export the sheet as a TIFF image
            var imgOptions = new ImageOrPrintOptions
            {
                // Note: ImageFormat property may not be available in some versions.
                // The default format is PNG; if TIFF is required, ensure the library version supports it.
                OnePagePerSheet = true,
                HorizontalResolution = 200,
                VerticalResolution = 200
            };

            // Render the worksheet to a TIFF file
            var renderer = new SheetRender(sheet, imgOptions);
            string tiffPath = "workbook.tiff";

            // Ensure the output directory exists (if any)
            string outputDir = Path.GetDirectoryName(tiffPath);
            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            try
            {
                // Save first page as TIFF (or default format if TIFF not supported)
                renderer.ToImage(0, tiffPath);
                Console.WriteLine($"Image file generated: {tiffPath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to generate image: {ex.Message}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
